def top_k(counts, k):
    """Return the k keys with the largest counts, ties broken by ascending key.

    counts is a dict of key -> int. k <= 0 gives []. k larger than the number of keys gives all keys.
    """
    if k <= 0:
        return []
    items = sorted(counts.items(), key=by_count_then_key)
    return [key for key, _ in items[:k]]


def merge(a, b):
    """Return a new dict with the counts of a and b added key by key. Neither input is modified."""
    out = dict(a)
    for key, count in b.items():
        out[key] = out.get(key, 0) + count
    return out


def normalize(counts):
    """Return key -> count / total as floats rounded to 4 places; an empty or all-zero dict gives {}."""
    total = sum(counts.values())
    if total == 0:
        return {}
    return {key: round(count / total, 4) for key, count in counts.items()}
